    t = t.strip()
    try:
        m = int(t)
        ok = 0 <= m <= 100
    except ValueError:
        ok = False
    g = "INVALID" if not ok else ("A" if m >= 70 else "B" if m >= 60 else "C" if m >= 50 else "F")
    counts[g] += 1
    print(g)
print(" ".join(f"{k}:{v}" for k, v in counts.items()))

