import sys
lines = sys.stdin.read().strip().split("\n")
n = int(lines[0])
todo, done = [], 0
for l in lines[1:1 + n]:
    t, p, s = [x.strip() for x in l.split(",")]
    if s == "done":
        done += 1
    else:
        todo.append((int(p), t))
for p, t in sorted(todo):
    print(f"[{p}] {t}")
print(f"Done: {done}")

