import sys
tasks = {}
for l in sys.stdin.read().strip().split("\n"):
    l = l.strip()
    if l.startswith("add "):
        t, p = l[4:].rsplit(",", 1)
        tasks[t.strip()] = int(p)
    elif l.startswith("done "):
        t = l[5:].strip()
        if t in tasks:
            del tasks[t]
        else:
            print(f"ERROR unknown task: {t}")
    elif l == "list":
        for t, p in sorted(tasks.items(), key=lambda kv: (kv[1], kv[0])):
            print(f"[{p}] {t}")
        print("---")
